package com.resumethinking.platform.matching;
import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="analysis_results")
public class AnalysisResultEntity { @Id @Column(nullable=false,length=64,columnDefinition="VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin") private String id; @Column(name="task_id",nullable=false,unique=true,length=64,columnDefinition="VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin") private String taskId; @Column(name="resume_id",nullable=false,length=64,columnDefinition="VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin") private String resumeId; @Column(name="resume_version",nullable=false) private long resumeVersion; @Lob @Column(name="payload_json",nullable=false,columnDefinition="JSON") private String payloadJson; @Column(name="completed_at",nullable=false) private Instant completedAt; protected AnalysisResultEntity(){} public AnalysisResultEntity(String id,AnalysisResult r,String json){this.id=id;taskId=r.taskId();resumeId=r.resumeId();resumeVersion=r.resumeVersion();payloadJson=json;completedAt=r.completedAt();} public String getTaskId(){return taskId;} public String getPayloadJson(){return payloadJson;} public Instant getCompletedAt(){return completedAt;} }
